module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg load;
    reg [1:0] ena;
    reg [99:0] data;
    wire [99:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    reg [99:0] expected_q;

    // Task to apply reset/load and check
    initial begin
        // Initialize inputs
        load = 0;
        ena = 2'b00;
        data = 100'h0;
        expected_q = 100'h0;

        @(posedge clk);
        #1;

        // Test 1: Synchronous Load
        load = 1'b1;
        ena = 2'b00;
        data = 100'h123456789ABCDEF012345678;
        expected_q = data;

        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("Error at Load: got %h, expected %h", q, expected_q);
        end

        // Disable load, test holding (ena = 2'b00)
        load = 1'b0;
        ena = 2'b00;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("Error at ena=00 (hold): got %h, expected %h", q, expected_q);
        end

        // Test 2: Rotate Right by 1 bit (ena = 2'b01)
        // Rotating right: LSB moves to MSB, others shift right.
        // If q = {q[99:0]}, right rotate means new_q = {q[0], q[99:1]}
        load = 1'b0;
        ena = 2'b01;

        repeat (5) begin
            expected_q = {expected_q[0], expected_q[99:1]};
            @(posedge clk);
            #1;
            if (q !== expected_q) begin
                errors = errors + 1;
                $display("Error at Rotate Right: got %h, expected %h", q, expected_q);
            end
        end

        // Test 3: Rotate Left by 1 bit (ena = 2'b10)
        // Rotating left: MSB moves to LSB, others shift left.
        // New_q = {q[98:0], q[99]}
        ena = 2'b10;
        repeat (5) begin
            expected_q = {expected_q[98:0], expected_q[99]};
            @(posedge clk);
            #1;
            if (q !== expected_q) begin
                errors = errors + 1;
                $display("Error at Rotate Left: got %h, expected %h", q, expected_q);
            end
        end

        // Test 4: Invalid/No Rotate (ena = 2'b11)
        ena = 2'b11;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("Error at ena=11 (hold): got %h, expected %h", q, expected_q);
        end

        // Test 5: Priority test - Load overrides enable
        load = 1'b1;
        ena = 2'b01; // rotate right requested, but load is active
        data = 100'hFEDCBA9876543210FEDCBA98;
        expected_q = data;

        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("Error at Load Priority: got %h, expected %h", q, expected_q);
        end

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
